const uint32_t BLOCK_DIM = 8;
const uint32_t TILE_NUM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvTransposed2dAsymmetricInputAsymmetricKernelPaddedCustomTilingData tiling;

    const gert::Shape* x_shape = context->GetInputShape(0); // [N, C_in, H, W]
    const gert::Shape* w_shape = context->GetInputShape(1); // [C_in, C_out, K_h, K_w]

    uint32_t n  = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(0));
    uint32_t ci = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(1));
    uint32_t h  = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(2));
    uint32_t w  = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(3));

    uint32_t ci_w = static_cast<uint32_t>(w_shape->GetOriginShape().GetDim(0));
    uint32_t co   = static_cast<uint32_t>(w_shape->GetOriginShape().GetDim(1));
    uint32_t kh   = static_cast<uint32_t>(w_shape->GetOriginShape().GetDim(2));
    uint32_t kw   = static_cast<uint32_t>(w_shape->GetOriginShape().GetDim(3));

    // basic sanity (C_in should match)
    (void)ci_w;

    uint64_t totalLength = static_cast<uint64_t>(n) * static_cast<uint64_t>(ci) * static_cast<uint64_t>(h) * static_cast<uint64_t>(w);
    if (totalLength == 0) {
        totalLength = 1;
    }

    context->SetBlockDim(BLOCK_DIM);

    tiling.set_totalLength(static_cast<uint32_t>(totalLength));
    tiling.set_tileNum(TILE_NUM);
    tiling.set_n(n);
    tiling.set_c_in(ci);
    tiling.set_h(h);
    tiling.set_w(w);
    tiling.set_c_out(co);
    tiling.set_k_h(kh);
    tiling.set_k_w(kw);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t* currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // x: [N, C_in, H, W], w: [C_in, C_out, K_h, K_w]
    const gert::Shape* x_shape = context->GetInputShape(0);
    const gert::Shape* w_shape = context->GetInputShape(1);

    int64_t N  = x_shape->GetOriginShape().GetDim(0);
    int64_t H  = x_shape->GetOriginShape().GetDim(2);
    int64_t W  = x_shape->GetOriginShape().GetDim(3);
    int64_t Cout = w_shape->GetOriginShape().GetDim(1);

    // For stride=(1,1) and padding=(K_h//2, K_w//2) with odd kernels, output H,W equal to input H,W
