    gert::Shape outShape;
    outShape.SetDimNum(4);
    outShape.SetDim(0, N);
    outShape.SetDim(1, Cout);
    outShape.SetDim(2, H);
    outShape.SetDim(3, W);
    y_shape->SetOriginShape(outShape);
    y_shape->SetStorageShape(outShape);
    return GRAPH_SUCCESS;
}

